1	/**
2	 * ending-comment.ts — which comment a run ended on, recorded and read back.
3	 *
4	 * ## Why a file at all
5	 *
6	 * A run ends two ways, and the machinery used to know only one of them. When the
7	 * model returns prose, `post_result_comment.ts` posts the report with the footer
8	 * (run link, tokens, metrics, tool trouble) attached. When a tool ends the session
9	 * — `create_pr`, `launch_sub_agent`, `request_close_issue`, `reload_environment` —
10	 * that tool posts its own turn-ending comment and the machinery skips, so the
11	 * footer never went out on those runs at all, and the token figure the metrics
12	 * report reads off comment footers (`token-line.ts` → `write_metrics_report.ts`)
13	 * missed every one of them.
14	 *
15	 * The two halves run in different processes, hours apart: the tool server writes
16	 * this record mid-run, and the machinery step reads it after the agent has
17	 * stopped. A file in `$ATOMATON_RUN_DIR` is the one place both can reach without
18	 * a second GitHub read, and the directory is per-run, so nothing outlives the run
19	 * it belongs to.
20	 *
21	 * ## The rule this serves
22	 *
23	 * The footer goes on the ONE comment that ended the run's turn — not on a second
24	 * comment beside it, and not on the artifacts a tool also leaves (sub-issue
25	 * bodies, PR bodies, dispatch notices), which outlive the run the footer is about.
26	 * `post_result_comment.ts` appends the footer onto the comment recorded here
27	 * instead of posting a new one.
28	 *
29	 * ## What it does not decide
30	 *
31	 * Not whether a comment ends a run's turn — the callers do, from the same fact
32	 * that decides their `session_ends` meta. A record written for a call that did
33	 * NOT end the session would put the footer on a comment while the run went on to
34	 * write another one, and the rule above would be broken by the very code that
35	 * holds it.
36	 */
37	import { existsSync, readFileSync, writeFileSync } from "node:fs";
38	import { gh } from "./gh.ts";
39	
40	export interface EndingComment {
41	  /** The comment's id, as `gh issue comment` printed it. */
42	  commentId: string;
43	  /** The issue or pull request the comment is on. */
44	  node: string;
45	}
46	
47	/** Where the record lives, or nothing when this run does not know its own directory. */
48	export function endingCommentPath(): string | undefined {
49	  const dir = (process.env.ATOMATON_RUN_DIR ?? "").trim();
50	  return dir ? `${dir}/ending-comment.json` : undefined;
51	}
52	
53	/**
54	 * The comment id in what `gh issue comment` printed, or nothing.
55	 *
56	 * `gh` prints the comment's URL — `.../issues/5#issuecomment-42` — and the number
57	 * after the fragment is the id the API PATCH takes. Empty output is a comment that
58	 * failed or a fake that printed nothing; the callers treat it as "no id to record",
59	 * which is what the machinery's own fallback is for.
60	 */
61	export function commentIdFromUrl(stdout: string): string | undefined {
62	  const match = /#issuecomment-(\d+)\s*$/.exec(stdout.trim());
63	  return match?.[1];
64	}
65	
66	/**
67	 * Record the comment a run ended on.
68	 *
69	 * Silent when the run's directory is unknown or the id is missing: the footer is
70	 * an addition to a comment that already went out, never a precondition for it, and
71	 * a recording that failed must not fail the tool that just posted successfully.
72	 */
73	export function recordEndingComment(commentId: string | undefined, node: string): void {
74	  if (!commentId) return;
75	  const path = endingCommentPath();
76	  if (!path) return;
77	  try {
78	    writeFileSync(path, JSON.stringify({ commentId, node } satisfies EndingComment));
79	  } catch (e) {
80	    console.error(`could not record the ending comment: ${(e as Error).message}`);
81	  }
82	}
83	
84	/**
85	 * The recorded comment, or nothing.
86	 *
87	 * Every failure here is a real outcome, not an error: without a record the
88	 * machinery posts as it always did, and the only cost is the old behavior for one
89	 * run. A file that is missing, unreadable or holds no id means "no comment to
90	 * append onto" — there is nothing to guess a comment from.
91	 */
92	export function readEndingComment(path: string | undefined): EndingComment | undefined {
93	  if (!path || !existsSync(path)) return undefined;
94	  try {
95	    const parsed = JSON.parse(readFileSync(path, "utf8")) as Partial<EndingComment>;
96	    if (typeof parsed.commentId !== "string" || !parsed.commentId) return undefined;
97	    return { commentId: parsed.commentId, node: parsed.node ?? "" };
98	  } catch {
99	    return undefined;
100	  }
101	}
102	
103	/**
104	 * Post a comment that ends a run's turn, and record it when the caller's result
105	 * ends the session.
106	 *
107	 * `sessionEnds` is the caller's own answer, known where the comment is built:
108	 * `create_pr` (`validationDispatched`), `launch_sub_agent` (`complete`). A caller
109	 * that learns it only after posting — `reload_environment`, whose dispatch is
110	 * attempted after the comment is up — passes nothing and calls
111	 * `recordEndingComment` itself once the dispatch has succeeded.
112	 *
113	 * Returns the comment id, so such a caller has it to record. A failed post is
114	 * logged, not thrown: the comment is one of several things the call has already
115	 * done by the time it can fail, and a throw would make the caller retry work
116	 * that did succeed.
117	 */
118	export function postTurnComment(args: {
119	  number: string;
120	  body: string;
121	  /** Passed through to `gh`; the CLI resolves the repository from the environment without it. */
122	  repo?: string;
123	  sessionEnds?: boolean;
124	}): string | undefined {
125	  const cmd = ["issue", "comment", args.number];
126	  if (args.repo) cmd.push("--repo", args.repo);
127	  cmd.push("--body", args.body);
128	  const { code, stdout, stderr } = gh(...cmd);
129	  if (code !== 0) {
130	    console.error(`could not comment on issue ${args.number}: ${stderr || stdout}`);
131	    return undefined;
132	  }
133	  const commentId = commentIdFromUrl(stdout);
134	  if (args.sessionEnds) recordEndingComment(commentId, args.number);
135	  return commentId;
136	}

