1	#!/usr/bin/env bun
2	/**
3	 * read_run_ending.ts — asks the run how it ended, instead of guessing from outside.
4	 *
5	 * The core records this itself. `atoma`'s runner classifies every ending —
6	 * `completed`, `iterations`, `runtime`, `stopped`, `loop`, `failed` — and writes it into the
7	 * session it just saved, as the last entry of `atoma_runs`. `write_metrics_report.ts`
8	 * has been reading those records for some time.
9	 *
10	 * The runner was not. It read the exit code, saw `2`, and then tested whether the
11	 * stop file existed:
12	 *
13	 *     if [ -f "${STOP_FILE}" ]; then stop_requested=true; else limit_reached=true; fi
14	 *
15	 * with a comment saying only this job could tell the two apart, "because only this
16	 * job asked". That was never true — the run knew, and had written it down.
17	 *
18	 * ## What the guess got wrong
19	 *
20	 * Two things, and one of them reaches a person.
21	 *
22	 * It collapsed two endings into one. `iterations` and `runtime` are different
23	 * ceilings, and the result comment says "ran out of iterations" for both. This
24	 * runner passes `--max-runtime-secs` and no `--max-iterations`, so the ceiling it
25	 * hits is ALWAYS the clock — which makes that sentence always the wrong one.
26	 *
27	 * And it raced. The stop file is written by a watcher while the run is going; a run
28	 * that reached its time limit at the moment somebody typed `/stop` exits for the
29	 * clock and is reported as stopped, because by then the file is there.
30	 *
31	 * ## The fallback
32	 *
33	 * A session that cannot be read leaves the old guess in place, because there is
34	 * nothing better to say and `stop_requested` decides whether a person is told their
35	 * stop landed. It is the only place left that tests the file, and it is reached only
36	 * when the run failed to write the session it was told to write.
37	 *
38	 * ## And whether it left a report
39	 *
40	 * The same file answers a second question, so it is opened once and asked both.
41	 * `domain/work/turn.ts` had no word for a run that ran to an ordinary end and said
42	 * nothing — those landed on `finished` and were read as completed — and the fact it
43	 * needs is in the session: the last assistant message either carries text or carries
44	 * only tool calls. Nothing is asked of the agent; `reported` is read off the record.
45	 *
46	 * The reading itself is `domain/record/closing-report.ts`, not here. It was here, and
47	 * that was wrong the moment the metrics report needed the same answer about the same
48	 * sessions: a second spelling of "did it report" is a second answer waiting to
49	 * disagree with this one.
50	 *
51	 * Usage:
52	 *   read_run_ending.ts --session FILE --exit-code N [--stop-file FILE]
53	 * Writes `ended_because=<word>` and `reported=<true|false>` to $GITHUB_OUTPUT.
54	 */
55	import { appendFileSync, existsSync, readFileSync } from "node:fs";
56	import { parseArgs } from "node:util";
57	import { leftClosingReport } from "../../domain/record/closing-report.ts";
58	import type { Session } from "../../domain/work/session.ts";
59	import { defineScript } from "./lib/script-ref.ts";
60	
61	export interface ReadRunEndingArgs {
62	  session: string;
63	  "exit-code": string;
64	  "stop-file"?: string;
65	}
66	
67	export const ref = defineScript<ReadRunEndingArgs>(import.meta.url);
68	
69	/** The exit status the core uses for an ending somebody asked for, session written. */
70	const SOFT_STOP = "2";
71	
72	/**
73	 * The saved session as a document, or `undefined` when there is nothing readable.
74	 *
75	 * Separate from the two questions below because both are asked of it. Anything
76	 * unreadable is "no session" rather than a failure: each caller already has the
77	 * answer it gives when the run wrote nothing.
78	 */
79	export function parseSession(raw: string | undefined): Session | undefined {
80	  if (raw === undefined) return undefined;
81	  try {
82	    return JSON.parse(raw) as Session;
83	  } catch {
84	    return undefined;
85	  }
86	}
87	
88	/** What the core wrote about the run that just finished, if it wrote anything. */
89	export function endingFromSession(session: Session | undefined): string | undefined {
90	  const runs = session?.atoma_runs;
91	  if (!Array.isArray(runs) || runs.length === 0) return undefined;
92	  const last = runs[runs.length - 1] as { ended_because?: unknown };
93	  return typeof last?.ended_because === "string" && last.ended_because !== "" ? last.ended_because : undefined;
94	}
95	
96	function main(): void {
97	  const { values } = parseArgs({
98	    args: Bun.argv.slice(2),
99	    options: { session: { type: "string" }, "exit-code": { type: "string" }, "stop-file": { type: "string" } },
100	  });
101	
102	  const exitCode = values["exit-code"] ?? "";
103	  const sessionPath = values.session ?? "";
104	  // One read, one parse, two questions, so both facts about this run come from the
105	  // same document. A session runs to tens of megabytes on a long thread, and opening
106	  // it twice also leaves room for it to change between the two answers.
107	  const session = parseSession(existsSync(sessionPath) ? readFileSync(sessionPath, "utf8") : undefined);
108	  const recorded = endingFromSession(session);
109	  const reported = leftClosingReport(session);
110	
111	  let ending: string;
112	  if (recorded !== undefined) {
113	    ending = recorded;
114	  } else if (exitCode === SOFT_STOP) {
115	    // The only remaining reader of the stop file, and only when the run did not
116	    // write the session it was told to write.
117	    const stopFile = values["stop-file"] ?? "";
118	    ending = stopFile !== "" && existsSync(stopFile) ? "stopped" : "runtime";
119	    console.error(`read_run_ending: no record in the session; guessing "${ending}" from the stop file`);
120	  } else {
121	    ending = exitCode === "0" ? "completed" : "failed";
122	    console.error(`read_run_ending: no record in the session; taking "${ending}" from exit ${exitCode || "(none)"}`);
123	  }
124	
125	  const githubOutput = process.env.GITHUB_OUTPUT;
126	  if (githubOutput) appendFileSync(githubOutput, `ended_because=${ending}\nreported=${reported}\n`);
127	  console.error(`read_run_ending: ended_because=${ending} reported=${reported}`);
128	}
